document.body.classList.toggle("super-admin-settings-active", nextSection === "settings");
const nextHash = `#${nextSection}`;
if (window.location.hash !== nextHash && window.history?.replaceState) {
  window.history.replaceState(null, "", nextHash);
}

for (const section of elements.sections) {
  section.hidden = section.dataset.superAdminSection !== nextSection;
}

for (const navItem of elements.sectionNavItems) {
  const isActive = navItem.dataset.superAdminSectionTarget === nextSection;
  navItem.classList.toggle("is-active", isActive);
  if (isActive) {
    navItem.setAttribute("aria-current", "page");
    navItem.setAttribute("aria-disabled", "true");
    navItem.setAttribute("tabindex", "-1");
  } else {
    navItem.removeAttribute("aria-current");
    navItem.removeAttribute("aria-disabled");
    navItem.removeAttribute("tabindex");
  }
}

const isServicesActive = serviceSectionNames.has(nextSection);
if (elements.servicesNavToggle) {
  elements.servicesNavToggle.classList.toggle("is-active", isServicesActive);
  elements.servicesNavToggle.setAttribute(
    "aria-expanded",
    isServicesActive ? "true" : "false",
  );
}

